mapper.select:
SELECT

FROM AccountInviteRewards a WHERE 1 = 1 

    AND a.registerAccountId = #{registerAccountId}


    AND a.registerEmail LIKE CONCAT('%',#{registerEmail}, '%')
    /** AND a.registerEmail = #{registerEmail} */


    AND a.inviteAccountId = #{inviteAccountId}


    AND a.inviteEmail LIKE CONCAT('%',#{inviteEmail}, '%')
    /** AND a.inviteEmail = #{inviteEmail} */


    AND a.rewardsAccountId = #{rewardsAccountId}


    AND a.rewardsEmail LIKE CONCAT('%',#{rewardsEmail}, '%')
    /** AND a.rewardsEmail = #{rewardsEmail} */


    AND a.rewardsSubAccountId = #{rewardsSubAccountId}


    AND a.rewardsSubEmail LIKE CONCAT('%',#{rewardsSubEmail}, '%')
    /** AND a.rewardsSubEmail = #{rewardsSubEmail} */


    AND a.rewardsRate LIKE CONCAT('%',#{rewardsRate}, '%')
    /** AND a.rewardsRate = #{rewardsRate} */


    AND a.rewardsBalance = #{rewardsBalance}


    AND a.rewardsLevel = #{rewardsLevel}


    AND a.rewardsTag LIKE CONCAT('%',#{rewardsTag}, '%')
    /** AND a.rewardsTag = #{rewardsTag} */


    AND a.rewardsStatus = #{rewardsStatus}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')
    /** AND a.remark = #{remark} */


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

order by a.createTime desc

select  a.id,a.unid,a.headUrl,a.email,sum(rewardsBalance) as total,a.referralCode as referralCode
from Account a,AccountInviteRewards b where a.id = b.rewardsAccountId

    AND a.id= #{id}


    AND a.unid= #{unid}


    AND a.referralCode= #{referralCode}

group by a.id

select  ifnull(sum(rewardsBalance), 0)                                                    as totalSum,
        count(*) as totalCnt,
        ifnull(sum(case when createTime > unix_timestamp(date(now())) * 1000 then rewardsBalance else 0 end),0)  as todaySum,
        ifnull(sum(case when createTime > unix_timestamp(date(now())) * 1000 then 1 else 0 end),0)  as todayCnt
from AccountInviteRewards r ,
     (
         select a.id,a.email from Account a,Account b,Account c where a.referralCode=b.invitationCode and  b.referralCode=c.invitationCode and c.id=#{firstLevelAccountId}
     ) c
where r.registerAccountId = c.id and  r.rewardsAccountId=#{rewardsAccountId}
